const $=id=>document.getElementById(id),node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};let epoch=0,state=null,exportId=null,busy=false;const retries=new Map();
function clear(){epoch++;state=null;exportId=null;$('report').replaceChildren();$('versions').replaceChildren();$('review').hidden=true;$('export').hidden=true;$('download-area').hidden=true;}
async function request(path,options={}){const token=sessionStorage.getItem('incident-session');if(!token)throw Error('请先登录');const response=await fetch('/api/incidents-v1'+path,{...options,headers:{Authorization:'Bearer '+token,...(options.body?{'Content-Type':'application/json'}:{}),...(options.key?{'Idempotency-Key':options.key}:{})}});if(!response.ok){const data=await response.json();if(response.status===401){sessionStorage.removeItem('incident-session');clear();}throw Error(data.error);}return response;}
async function api(path,options={}){return (await request(path,options)).json();}
async function guard(fn){try{await fn();}catch(e){$('status').textContent=e.message;}}
async function write(path,body){const serialized=JSON.stringify(body),identity=path+serialized,entry=retries.get(identity)??crypto.randomUUID();retries.set(identity,entry);const result=await api(path,{method:'POST',body:serialized,key:entry});retries.delete(identity);return result;}
async function read(){const current=++epoch,id=$('report-id').value,project=$('project').value;state=null;$('report').replaceChildren();$('review').hidden=true;$('export').hidden=true;$('download-area').hidden=true;exportId=null;const result=await api(`/reports/${encodeURIComponent(id)}?projectId=${encodeURIComponent(project)}`);if(current!==epoch)return;state=result;sessionStorage.setItem('report-last',JSON.stringify({project,id,incident:result.report.incidentId}));$('incident').value=result.report.incidentId;const root=$('report');root.append(node('h2',`报告 v${result.report.version} · ${result.status}`),node('p',`作者 ${result.report.authorId} · 原草稿 ${result.report.investigationId}`),node('p',`证据摘要 ${result.report.evidenceManifestDigest}`));if(result.review)root.append(node('p','当前独立复核编号：'+result.review.reviewId));if(result.invalidation)root.append(node('p','失效原因：'+result.invalidation.reason));for(const historicalReview of result.reviewHistory??[])root.append(node('p',`历史复核 ${historicalReview.actorId}：${historicalReview.decision}；理由：${historicalReview.reason}`));for(const f of result.report.snapshot.findings){const section=document.createElement('section');section.append(node('h3',`${f.type} / ${f.origin}`),node('p',f.statement));for(const [label,refs] of [['依据',f.evidenceRefs],['反证',f.counterEvidenceRefs]])for(const r of refs)section.append(node('p',`${label} ${r.id} [${r.start},${r.end})`),node('pre',r.quote));root.append(section);}root.append(node('h3','缺项'),node('pre',JSON.stringify(result.report.snapshot.gaps,null,2)),node('h3','费用快照'),node('pre',JSON.stringify(result.report.snapshot.expenseSnapshot,null,2)));root.append(node('p','全部复核历史和原稿保留；已接受报告也不等于引用内容真实。'));$('review').hidden=result.status==='invalidated';$('export').hidden=result.status!=='reviewed';$('status').textContent='报告状态已刷新';}
async function list(){clear();const current=epoch,items=await api(`/incidents/${encodeURIComponent($('incident').value)}/reports?projectId=${encodeURIComponent($('project').value)}`);if(current!==epoch)return;$('expected').value=items.at(-1)?.version??0;for(const r of items){const b=node('button',`v${r.version} · ${r.status} · ${r.reportId}`);b.onclick=()=>guard(async()=>{$('report-id').value=r.reportId;await read();});$('versions').append(b);}$('status').textContent=`${items.length} 个报告版本`;}
$('list').onsubmit=e=>{e.preventDefault();guard(list);};$('read').onsubmit=e=>{e.preventDefault();guard(read);};
async function operation(fn){if(busy)return;busy=true;try{await fn();}finally{busy=false;}}
$('publish').onsubmit=e=>{e.preventDefault();guard(()=>operation(async()=>{const current=epoch,result=await write(`/incidents/${encodeURIComponent($('incident').value)}/reports`,{projectId:$('project').value,investigationId:$('investigation').value,expectedVersion:Number($('expected').value)});if(current!==epoch)return;$('report-id').value=result.report.reportId;$('expected').value=result.report.version;await read();}));};
$('review').onsubmit=e=>{e.preventDefault();guard(()=>operation(async()=>{if(!state)throw Error('请重新读取报告');const selected=state,current=epoch;await write(`/reports/${selected.report.reportId}/reviews`,{projectId:$('project').value,expectedVersion:selected.report.version,manifestDigest:selected.report.evidenceManifestDigest,expectedReviewId:selected.review?.reviewId??null,decision:$('decision').value,reason:$('reason').value});if(current===epoch){$('reason').value='';await read();}}));};
$('export').onsubmit=e=>{e.preventDefault();guard(()=>operation(async()=>{if(!state)throw Error('请重新读取报告');const current=epoch,result=await write(`/reports/${state.report.reportId}/exports`,{projectId:$('project').value,expectedVersion:state.report.version,reviewId:state.review.reviewId,audienceActorId:$('audience').value,profile:'redacted_metadata_v1'});if(current!==epoch)return;exportId=result.exportId;$('export-info').textContent=`导出 ${exportId}，截止 ${result.expiresAt}`;$('download-area').hidden=false;}));};
$('retrieve').onsubmit=e=>{e.preventDefault();exportId=$('received-export').value;$('export-info').textContent='收到的索引包将按当前账号和最新复核状态鉴权';$('download-area').hidden=false;};
$('download').onclick=()=>guard(async()=>{if(!exportId)throw Error('请创建索引包');const current=epoch,id=exportId,response=await request(`/report-exports/${encodeURIComponent(id)}?projectId=${encodeURIComponent($('project').value)}`),blob=await response.blob();if(current!==epoch)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`investigation-${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='已鉴权下载脱敏索引包';});
$('revoke').onsubmit=e=>{e.preventDefault();guard(async()=>{if(!exportId)throw Error('请先创建索引包');const current=epoch;await api(`/report-exports/${encodeURIComponent(exportId)}/revocation`,{method:'POST',body:JSON.stringify({projectId:$('project').value,reason:$('revoke-reason').value})});if(current===epoch){$('download-area').hidden=true;exportId=null;$('status').textContent='后续下载已撤销';}});};
for(const id of ['project','incident'])$(id).oninput=()=>{clear();sessionStorage.removeItem('report-last');};
$('logout').onclick=()=>guard(async()=>{try{await api('/session',{method:'DELETE'});}finally{sessionStorage.removeItem('incident-session');sessionStorage.removeItem('report-last');clear();$('reason').value='';$('audience').value='';$('report-id').value='';$('status').textContent='已退出';}});
$('project').value=sessionStorage.getItem('incident-project')||'';try{const saved=JSON.parse(sessionStorage.getItem('report-last')||'null');if(saved&&sessionStorage.getItem('incident-session')){$('project').value=saved.project;$('incident').value=saved.incident;$('report-id').value=saved.id;guard(read);}}catch{sessionStorage.removeItem('report-last');}



